const KEY='ab-pool-demo-v1',SAT=100000000;
function initial(){return {balance:10000000,outcome:null,bets:[{name:'예시 참여자 1',side:'A',amount:3000000,mine:false},{name:'예시 참여자 2',side:'B',amount:2000000,mine:false},{name:'예시 참여자 3',side:'A',amount:1000000,mine:false}]};}
let state=initial(),selected='A';
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&Number.isSafeInteger(saved.balance)&&saved.balance>=0&&[null,'A','B','cancel'].includes(saved.outcome)&&Array.isArray(saved.bets)&&saved.bets.every(b=>['A','B'].includes(b.side)&&Number.isSafeInteger(b.amount)&&b.amount>0&&b.amount<=100000000&&typeof b.mine==='boolean'))state=saved;}catch{}
const $=id=>document.getElementById(id),fmt=n=>(n/SAT).toFixed(8),total=side=>state.bets.filter(b=>!side||b.side===side).reduce((n,b)=>n+b.amount,0);
function amount(){const v=$('amount').value.trim();return /^(?:0|[1-9]\d{0,6})(?:\.\d{1,8})?$/.test(v)?Math.round(Number(v)*SAT):NaN;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{$('message').textContent='저장 공간을 사용할 수 없습니다. 탭을 닫으면 기록이 사라질 수 있습니다.';}}
function payouts(bets,outcome){const sum=bets.reduce((s,b)=>s+b.amount,0),win=bets.reduce((s,b)=>s+(b.side===outcome?b.amount:0),0);if(outcome==='cancel'||!win)return bets.map(b=>b.amount);let result=bets.map(b=>b.side===outcome?Number(BigInt(sum)*BigInt(b.amount)/BigInt(win)):0);let remainder=sum-result.reduce((a,b)=>a+b,0);for(let i=0;remainder>0;i++){if(bets[i].side===outcome){result[i]++;remainder--;}}return result;}
function render(){const t=total(),a=total('A'),b=total('B');$('question').textContent='다음 라운드의 결과는 A일까요?';$('status').textContent=state.outcome?(state.outcome==='cancel'?'취소 · 환불 완료':state.outcome+' 승리 · 정산 완료'):'● 참여 진행 중';for(const side of ['A','B']){const n=total(side);$(side.toLowerCase()+'Percent').textContent=(t?n/t*100:50).toFixed(1)+'%';$(side.toLowerCase()+'Info').textContent=state.bets.filter(x=>x.side===side).length+'건 · '+fmt(n)+' BTC';$('choose'+side).classList.toggle('active',selected===side);$('choose'+side).setAttribute('aria-pressed',selected===side);}$('barA').style.width=(t?a/t*100:50)+'%';$('pool').textContent=fmt(t)+' BTC';$('people').textContent=(state.bets.filter(b=>!b.mine).length+(state.bets.some(b=>b.mine)?1:0))+'명';$('balance').textContent=fmt(state.balance)+' BTC';$('selection').textContent=selected+' · '+(selected==='A'?'그렇다':'아니다');const v=amount();$('estimate').textContent=!state.outcome&&v>0&&v<=state.balance?fmt(Number(BigInt(t+v)*BigInt(v)/BigInt(total(selected)+v)))+' BTC':'—';$('submit').disabled=!!state.outcome;$('submit').textContent=state.outcome?'종료된 라운드':selected+'에 참여하기 ↗';const rows=$('history');rows.replaceChildren();const paid=state.outcome?payouts(state.bets,state.outcome):null;state.bets.forEach((bet,i)=>{const tr=document.createElement('tr');[bet.mine?'나':bet.name,bet.side,fmt(bet.amount),paid?fmt(paid[i]):'미정'].forEach(value=>{const td=document.createElement('td');td.textContent=value;tr.append(td);});rows.append(tr);});for(const id of ['settleA','settleB','cancel'])$(id).disabled=!!state.outcome;}
for(const side of ['A','B'])$('choose'+side).onclick=()=>{selected=side;render();};$('amount').oninput=render;document.querySelectorAll('[data-amount]').forEach(b=>b.onclick=()=>{$('amount').value=b.dataset.amount;render();});
$('betForm').onsubmit=e=>{e.preventDefault();if(state.outcome)return;const v=amount();if(!Number.isSafeInteger(v)||v<=0||v>state.balance){$('message').textContent='잔액 이내의 금액을 소수점 8자리까지 입력하세요.';return;}state.balance-=v;state.bets.push({name:'나',side:selected,amount:v,mine:true});$('message').textContent=selected+'에 '+fmt(v)+' 모의 BTC로 참여했습니다.';save();render();};
function settle(outcome){if(state.outcome)return;if(!confirm(outcome==='cancel'?'라운드를 취소하고 전액 환불할까요?':outcome+' 승리로 확정하고 모의 배당을 정산할까요?'))return;const paid=payouts(state.bets,outcome);state.balance+=paid.reduce((s,p,i)=>s+(state.bets[i].mine?p:0),0);state.outcome=outcome;$('message').textContent='정산이 완료되었습니다. 참여 내역에서 수령액을 확인하세요.';save();render();}
$('settleA').onclick=()=>settle('A');$('settleB').onclick=()=>settle('B');$('cancel').onclick=()=>settle('cancel');$('reset').onclick=()=>{if(confirm('모든 모의 기록을 삭제하고 초기 상태로 돌아갈까요?')){state=initial();$('message').textContent='데모를 초기화했습니다.';save();render();}};render();

$('copyAddress').onclick=async()=>{try{await navigator.clipboard.writeText($('receiveAddress').textContent);$('copyStatus').textContent='주소를 복사했습니다.';}catch{$('copyStatus').textContent='자동 복사가 지원되지 않습니다. 위 주소를 직접 선택해 복사하세요.';}};
